"""Build the Understandable curriculum from original, criterion-specific teaching notes."""
import json
from pathlib import Path
from understandable_extension import EXTENSION
from understandable_walkthroughs import WALKTHROUGHS
from understandable_decisions import DECISIONS
from understandable_review import REVIEW
from understandable_practice import PRACTICE, GROUP_GUIDANCE
from understandable_cases import CASES, PRE_CASES

REFERENCE = Path(__file__).resolve().parents[2] / 'frontAccEase-Backend/app/wcag_formatted.json'
DATA = [
('3.1.1', 'Identify the default human language in markup', 'Screen readers use language information to select pronunciation rules and voices. A page in Filipino announced with an English voice can make familiar words difficult to recognize. The default language describes the human language of the main content, not the programming language or a visitor’s identity.', 'Set the language on the root html element, for example <html lang="en"> for an English page. Choose a valid language tag appropriate to the actual content; setting the same tag on every site regardless of language defeats its purpose. Pages with several languages still need an appropriate default for the page.', 'A browser setting and an HTML lang attribute serve different purposes. Inspect the page source and the accessibility tree, then test text using a screen reader with automatic language switching. If the page is mostly Filipino, use an appropriate Filipino language tag rather than assuming English.', 'Inspect two pages with different main languages. Record the root lang value, compare it with the predominant text, and correct any mismatch.', 'Which markup identifies the default language of an English page?', '<html lang="en">', '<html charset="en">', 'A language tag on the root identifies the human language of the page.'),
('3.1.2', 'Mark passages whose human language differs from the page', 'When a sentence switches from English to French, a synthesizer may continue applying English pronunciation unless the passage identifies its language. Language information is programmatic, so it can help speech and other tools without relying on a visual flag.', 'Mark a meaningful foreign-language passage with a language tag, such as <span lang="fr">Bonjour</span> inside an English page. Apply it to the appropriate phrase, not an unrelated container. The criterion has exceptions for proper names, technical terms, indeterminate language, and words or phrases that have become part of the surrounding language.', 'Do not assume every borrowed word needs a language change. Review the context and applicable exceptions. Test the page with language switching enabled and check that the surrounding English resumes afterward. A visual label alone does not expose the language of the passage programmatically.', 'Create a paragraph with an English sentence and a French quotation. Mark the quotation, inspect the resulting DOM, and listen with a screen reader.', 'How can a French quotation in an English page identify its language?', '<span lang="fr">Bonjour</span>', '<span class="french">Bonjour</span>', 'The lang attribute supplies a machine-readable language tag.'),
('3.1.3', 'Provide a way to identify meanings of unusual words', 'Specialist terms, idioms, and words used in a restricted sense can prevent readers from understanding content even when each word is pronounced correctly. A technical student may understand a word differently from a specialist audience. This AAA criterion asks for a mechanism to identify intended definitions in the relevant cases.', 'Provide a contextual definition, a glossary, or a linked explanation. For example, after first using “token” in an authentication lesson, explain whether it means a temporary credential or a physical object. Place help where readers can find it without losing their place.', 'A dictionary link is not always enough when the intended meaning is a domain-specific sense. Check that the definition matches the way the word is used, and keep glossary links accessible from keyboard and assistive technology. Common terms do not automatically become unusual words merely because they appear in a technical article.', 'Choose three technical or idiomatic terms in a page. Write context-specific definitions and link each to an accessible glossary or explanation.', 'What makes a glossary useful for a specialized term?', 'It explains the meaning intended in that context', 'It lists only unrelated dictionary meanings', 'The reader needs the meaning used by the content.'),
('3.1.4', 'Provide a mechanism for identifying expansions of abbreviations', 'Abbreviations save space but may hide meaning from a reader encountering a subject for the first time. An abbreviation may have several expansions; for example, “API” is recognizable to some developers but unfamiliar to new students.', 'Give the expansion at first use or provide an accessible glossary. “Application programming interface (API)” makes the relationship explicit. An abbr element with an appropriate title may help some users, but title display and assistive technology support vary, so visible expansion is a reliable approach.', 'Do not rely only on a mouse hover tooltip. Readers using touch, keyboard, or speech may not discover it. This AAA criterion includes exceptions for abbreviations that are part of the language; check the complete requirement and context before concluding that an expansion is necessary.', 'Review a documentation page for abbreviations. Expand each applicable abbreviation in context and verify that the meaning can be reached without a mouse.', 'What is a useful first occurrence of an unfamiliar abbreviation?', 'Application programming interface (API)', 'API with only an unexplained icon', 'The expansion is directly available in the surrounding text.'),
('3.1.5', 'Recognize when a reading-level alternative is needed', 'Dense sentences and specialized vocabulary can exclude readers with cognitive or language disabilities and people new to a topic. A technically accurate page can still be hard to understand. The AAA criterion concerns text requiring reading ability more advanced than the lower secondary education level, after removing proper names and titles.', 'Provide supplemental content or a version that does not require reading ability above that level when the criterion applies. A plain-language summary, a diagram with accessible explanation, or an alternative version can help, provided it preserves the information needed for the task. Do not assume that shortening a page automatically makes it understandable.', 'Compare the original and alternative for omissions, undefined terms, and actionable details. Ask representative readers to explain the instructions or complete a task. Automated readability formulas can flag difficult passages but do not establish understanding or replace assessment of the criterion and its exceptions.', 'Rewrite a complex enrollment instruction in plain language. Ask a reader to locate the deadline and required documents in both versions, and revise any ambiguity.', 'What can help when text requires a reading ability above the specified level?', 'A useful supplemental explanation or simpler version', 'Removing essential instructions from the page', 'The alternative needs to make the original content understandable without losing task information.'),
('3.1.6', 'Provide pronunciation where meaning depends on it', 'Some words are spelled the same but pronounced differently depending on meaning. A synthesizer or reader may choose the wrong pronunciation when context alone is insufficient. This can alter meaning even when the spelling is correct.', 'Provide a way to determine the intended pronunciation for words whose meaning is ambiguous without it. Depending on the content, a pronunciation guide, phonetic text, or accessible audio can supply the information. Make the guide available alongside the relevant word or through a clear link.', 'Do not provide only audio without considering people who cannot hear it; a written pronunciation guide may also be useful. A recording should itself be accessible through appropriate alternatives. Check with language specialists where a pronunciation or notation is uncertain.', 'Find a word whose intended meaning changes with pronunciation in a sample sentence. Add a pronunciation guide and test whether a reader can identify the intended meaning.', 'When is a pronunciation mechanism particularly relevant?', 'When the intended meaning is ambiguous without pronunciation', 'Whenever a page contains any word', 'The criterion addresses ambiguity that depends on pronunciation.'),
('3.2.1', 'Avoid unexpected context changes on focus', 'Focus identifies the interface element currently ready for keyboard interaction. Merely moving focus to a control should not unexpectedly take a person to another page, submit a form, or open a new window. Such changes can disorient keyboard and screen-reader users who are exploring rather than choosing.', 'Separate focus from activation. A menu item can receive focus without navigating; navigation occurs after an intentional action such as pressing Enter or clicking. Showing a non-disruptive focus indicator or updating a small description is not necessarily a change of context.', 'A focus event can be caused by keyboard navigation, script, or assistive technology. Do not attach a redirect to onfocus. Test with Tab and Shift+Tab from the start of the page and observe whether the location, focus, or whole view changes unexpectedly.', 'Tab through a navigation menu and form. Record any focus-triggered context change, then revise the control so the user explicitly activates the action.', 'What should happen when a navigation link receives focus?', 'It remains focused until the user activates it', 'It immediately redirects the user', 'Moving focus is not the same as choosing a destination.'),
('3.2.2', 'Make the effect of changing a control predictable', 'A user may change a value while reviewing options, using a keyboard, or entering data. If the change immediately submits a form or moves to another page without advance warning, the result can interrupt that work. A change of context is more significant than an ordinary update within the current view.', 'Use an explicit Apply, Search, or Continue button for consequential changes, or clearly inform the user of the behavior before they interact. For example, a language selector that changes pages immediately needs advance notice when that behavior causes a context change.', 'A select element with an onchange redirect can make arrow-key exploration trigger navigation. Test the actual keyboard behavior and announce instructions before the control. Updating a nearby price without moving focus or navigating is not automatically the same as a context change.', 'Build a filter with a select and an Apply button. Test choosing several options with the keyboard and confirm that navigation or submission occurs only when expected.', 'How can a filter avoid an unexpected submission when its value changes?', 'Provide an explicit Apply button', 'Redirect immediately on every selection without notice', 'An explicit action makes the consequential change predictable.'),
('3.2.3', 'Keep repeated navigation in a consistent relative order', 'People learn where common navigation appears and use that knowledge on later pages. If links move unpredictably, users must repeatedly search, which increases cognitive effort and slows keyboard navigation.', 'For navigation mechanisms repeated across multiple pages, keep their relative order consistent unless the user initiates a change. A header with Home, Courses, and Help should preserve that sequence across pages where those links recur. Individual pages may contain additional links; relative order does not mean every page must have an identical menu.', 'Compare pages in the same set rather than comparing unrelated applications. Responsive layouts can change visual presentation while preserving a meaningful relative order. User-selected customization is permitted by the criterion, but do not silently reorder links for everyone.', 'Compare the main navigation on three course pages, recording link order in the DOM and visually. Correct inconsistent ordering and recheck keyboard navigation.', 'What does consistent navigation primarily require?', 'Repeated navigation items keep the same relative order', 'Every page must contain exactly the same content', 'The criterion concerns the relative order of repeated navigation mechanisms.'),
('3.2.4', 'Identify components with the same function consistently', 'A user transfers knowledge from one page to another. If identical functions have unrelated names or icons, a familiar action can appear to be a different action. Conversely, reusing one label for different actions can be misleading.', 'Use consistent labels and accessible names for components that have the same functionality within a set of pages. For example, use “Search” consistently for the same search function rather than alternating between “Find”, “Go”, and an unlabeled magnifier.', 'Consistency does not mean unrelated controls must share a label or that every icon must look identical. Include accessible names in the review: two icons that look alike but have contradictory screen-reader names can still confuse users. Check surrounding context and function.', 'Inventory repeated search and help controls across a site. Compare visible labels, accessible names, and actual behavior; correct mismatches for equivalent functions.', 'How should the same search function be identified across pages?', 'With a consistent name such as Search', 'With unrelated names on each page', 'Consistent identification helps readers recognize the same functionality.'),
('3.2.5', 'Ensure changes of context occur on request or can be disabled', 'Unexpected changes in page, focus, or window can disrupt a task. At AAA, the criterion requires changes of context to be initiated by user request, or a mechanism to turn such changes off. This is broader than the specific focus and input situations addressed by related criteria.', 'Use controls that make actions clear: open a new page when a user activates a link, and let the user choose whether automatic transitions occur. Where an automatic context change exists, provide a way to disable it. A clearly identified explicit action gives the user control.', 'Do not confuse any small update with a change of context. Assess whether the change substantially affects the user’s interaction, such as moving focus, navigating, or changing the viewport. Test automatically timed flows as well as focus and input events.', 'Observe a multi-step interface for automatic redirects or focus changes. Document which changes are user initiated, and provide an accessible way to disable the others.', 'How can an automatic context change meet this AAA requirement?', 'Offer a mechanism to turn it off', 'Hide the setting and redirect without warning', 'Users must initiate context changes or have a way to disable them.'),
('3.2.6', 'Place repeated help mechanisms consistently', 'When people need assistance, predictability helps them find it quickly. A help link that moves from the header to an unrelated footer position on each page forces users to search again, especially when a task is already difficult.', 'For applicable help mechanisms repeated across pages in a set, keep their relative order with respect to other page content consistent unless the user changes it. Examples include human contact details, a human contact mechanism, self-help information, and a fully automated contact mechanism.', 'The criterion applies when the same help mechanism is repeated; it does not require every page to add every kind of help. Compare positions across desktop and mobile pages and review source order as well as visual presentation.', 'Map the Help link and contact options across three pages. Check their relative placement and propose a consistent location that works at different viewport sizes.', 'What does consistent help require when the same help link appears on several pages?', 'Keep its relative position consistent', 'Add every possible type of help to every page', 'The requirement concerns consistent placement of repeated applicable help mechanisms.'),
('3.3.1', 'Identify input errors in text', 'A red border may be easy to miss and does not tell a screen-reader user what failed. An error needs to identify the problematic item and describe the error in text so that the person can understand what to fix.', 'After validation, provide a clear message such as “Email address: enter an address in the form name@example.com.” Associate the message with the field, for example with aria-describedby, and communicate invalid state where appropriate. A summary can link to errors when a form is long.', 'Do not rely only on color, an icon, or a generic “Invalid input” message detached from its field. Ensure the message describes the error without revealing sensitive information. Test server-side errors as well as client-side checks and verify messages remain visible when revisiting fields.', 'Submit a form with a missing email address. Add a text error, connect it to the field, and verify the field and message with keyboard and a screen reader.', 'Which error response identifies the problem in text?', 'Email address: enter a valid email address', 'A red border with no message', 'A text description identifies both the affected item and its error.'),
('3.3.2', 'Provide labels or instructions for inputs', 'People need to know what information a field expects before making an error. A placeholder that disappears on typing can remove the only visible instruction and leave readers uncertain about the field’s purpose.', 'Give each input a meaningful label and provide instructions where required, such as the expected date format or mandatory fields. In HTML, connect a label using for and id, and associate supporting text with aria-describedby when appropriate. Group related radio buttons with fieldset and legend.', 'A programmatic accessible name and visible instructions are related but distinct concerns. A screen-reader-only name does not necessarily help a sighted person who cannot infer a field’s purpose. Avoid placing essential format rules solely in an error after submission.', 'Create a date field with a visible label and format guidance. Verify the association in the accessibility tree and ask a new user to complete the field before seeing any error.', 'Which design helps users know what to enter before an error?', 'A visible label with relevant format instructions', 'An unlabeled field with disappearing placeholder text', 'Labels and instructions tell users what the input expects.'),
('3.3.3', 'Suggest corrections when known and appropriate', 'Knowing that an entry is invalid is useful; knowing how to correct it makes recovery much easier. A generic rejection may force users to guess a format or repeat the same failure.', 'When an input error is detected and a correction suggestion is known, provide it unless doing so would jeopardize security or the purpose of the content. For example, “Enter the date as DD/MM/YYYY” supplies actionable guidance when the format is known.', 'Do not expose a secret or confirm account existence merely to provide a suggestion. Error identification and error suggestion work together: identify the field, describe what went wrong, and provide safe guidance. Ensure a suggestion does not silently overwrite a user’s entry.', 'Test a date field with an invalid format and a sign-in form with an invalid credential. Write helpful, safe messages for each without exposing sensitive information.', 'When a known date format is entered incorrectly, what is a useful response?', 'Enter the date as DD/MM/YYYY', 'Something is wrong, with no additional guidance', 'A known safe correction helps the user recover.'),
('3.3.4', 'Protect important legal, financial, and data submissions from errors', 'An accidental financial transfer, legal acceptance, or modification of stored data can have serious consequences. Users may misread an amount, activate the wrong control, or submit before noticing an error. Recovery needs to be designed into the workflow.', 'For the covered submissions, provide at least one of the specified safeguards: the submission is reversible, entered data is checked for errors with a chance to correct them, or a review, confirmation, and correction mechanism is available before finalizing. The exact scope and exceptions should be read in the complete criterion.', 'A confirmation screen that merely says “Are you sure?” without showing details does not help a user review the amount or recipient. Display meaningful values and allow editing before final action. Clearly distinguish saving a draft from committing a transaction.', 'Design a transfer review page that shows recipient and amount and lets the user change either before confirming. Test with keyboard and explain how the safeguard prevents an error.', 'Which safeguard can protect an important financial submission?', 'Review and correct the amount before final confirmation', 'Submit immediately with no review or recovery', 'A review and correction step is one of the permitted safeguards.'),
('3.3.5', 'Offer context-sensitive help', 'General documentation can be useful, but someone filling a specific field often needs an explanation of that field at the moment of entry. Context-sensitive help relates to the current task or control rather than requiring the user to search an unrelated manual.', 'Place an explanation next to an input or link to help that opens at the relevant topic. For an account name, explain restrictions and give an example. Make the help available to keyboard, touch, and assistive-technology users without removing their work.', 'Do not hide the only help in a hover-only tooltip. Consider whether opening a help dialog moves focus predictably and whether closing it returns focus to the initiating control. Help is different from an error message: it supports the user before or during input.', 'Add contextual help to a password field and verify that a keyboard user can open, read, and leave the help while retaining entered data.', 'Which is an example of context-sensitive help?', 'A nearby explanation of the current field’s expected value', 'A generic homepage with no connection to the task', 'The help addresses the user’s current context.'),
('3.3.6', 'Apply error-prevention safeguards to all user submissions', 'A small form submission can still have consequences for a person who made a mistake. The AAA criterion extends the error-prevention choices to submissions involving user input beyond the important categories covered by the AA criterion.', 'Provide at least one of the allowed approaches: reversibility, input checking with an opportunity to correct errors, or a mechanism to review, confirm, and correct information before final submission. Choose a safeguard appropriate to the action rather than adding a meaningless confirmation dialog.', 'A reversible action needs an effective way to undo it. A validation check should catch relevant errors and let the user fix them; it should not silently discard input. A review page must let a user correct details before committing the submission.', 'Pick an ordinary profile update. Add an effective undo, validation and correction, or review-and-confirm path, then test a deliberately incorrect value.', 'How does the AAA error-prevention criterion differ from the AA criterion?', 'It applies the safeguards to submissions involving user input more broadly', 'It applies only to financial transactions', 'The enhanced criterion extends protection beyond the categories in the AA criterion.'),
('3.3.7', 'Avoid asking users to re-enter information in the same process', 'Repeatedly entering the same address or other information can be difficult for people with memory, motor, or cognitive disabilities. It can also introduce inconsistencies in a multi-step process.', 'When information previously entered by or provided to the user is needed again in the same process, auto-populate it or make it available for selection. For example, offer the previously entered shipping address as a selectable billing address. The user should be able to inspect and change it when appropriate.', 'The criterion includes exceptions when re-entry is essential, needed for security, or the previously entered information is no longer valid. It does not prohibit an optional alternative address. Distinguish a genuinely new process from steps within a single process, and protect sensitive data appropriately.', 'Build a checkout flow that offers the shipping address for billing. Test accepting it, editing it, and choosing a different address without retyping unnecessarily.', 'How can a checkout avoid redundant entry?', 'Let the user select the previously entered address', 'Require the user to type the same address again without a reason', 'Making previously supplied information selectable avoids unnecessary re-entry.'),
('3.3.8', 'Provide accessible authentication without mandatory cognitive-function tests', 'A sign-in that requires a person to remember or transcribe a secret, solve a puzzle, or interpret distorted characters may prevent access. Password managers, paste, and device-based authentication can reduce memory and transcription burdens.', 'For each authentication step that uses a cognitive function test, provide an alternative without such a test or a mechanism that assists with it, unless an applicable exception applies. The minimum criterion has exceptions for object recognition and identifying personal content. Supporting password managers and paste can be assisting mechanisms; verify that the actual workflow permits them.', 'Do not assume a one-time code is automatically accessible if the user must memorize and retype it and no assistance is provided. An authentication alternative must remain available throughout the relevant step. Test with a password manager and paste, and examine recovery and multi-factor steps too.', 'Audit a sign-in and its second factor. Identify each memory or transcription demand, then test password-manager fill, paste, or an alternative that removes the demand.', 'Which can help satisfy the minimum authentication criterion for a password field?', 'Allowing password-manager fill and paste', 'Blocking paste and requiring memorization', 'Assistance can reduce the cognitive burden of remembering or transcribing a password.'),
('3.3.9', 'Apply the enhanced accessible-authentication requirement', 'The enhanced AAA criterion removes the minimum criterion’s exceptions for recognizing objects and identifying personal content. A visual puzzle or selecting a familiar photograph can still be inaccessible to some people, even if it avoids a conventional password.', 'For each authentication step involving a cognitive function test, provide an alternative that does not require that test or a mechanism that assists the person in completing it. An accessible device-based sign-in or a properly supported password manager may help, depending on the complete flow.', 'Distinguish the enhanced requirement from the minimum requirement: the object-recognition and personal-content exceptions are not available here. Evaluate enrollment, sign-in, second factor, and recovery separately. A biometric method is useful only if the person can use the device and another accessible path is available when needed.', 'Compare an image-selection challenge and a passkey or password-manager flow. Identify cognitive tests, available assistance, and any inaccessible step in recovery.', 'Which exception from the minimum criterion is absent from the enhanced criterion?', 'Object recognition and identification of personal content', 'The availability of an assisting mechanism', 'The enhanced criterion does not include those two exceptions.')
]

# Separate examples deliberately follow each criterion rather than treating all
# language, navigation, or form requirements as interchangeable.
DETAILS = {
'3.1.1': ('A bilingual course home page is mostly written in English, but its HTML has no language setting. Speech output may use a voice selected for an unrelated language. Put lang="en" on the root element, then mark any applicable language changes on the passages themselves. The page language is the predominant language, not necessarily the language of every word.', '<html lang="en">\n  <head><title>Course overview</title></head>\n  <body><h1>Welcome</h1></body>\n</html>', 'A server-side template should set the value for every localized page, including error pages. Inspect the final rendered HTML after localization; a translation service that changes the text but leaves lang="en" on a Filipino page introduces a mismatch. The attribute identifies a language; it does not translate content or ensure that a particular voice is installed.'),
'3.1.2': ('A recipe written in English quotes a full French sentence. Without a language change, a speech synthesizer may apply English pronunciation to the quotation. Put lang="fr" on the quotation while leaving the surrounding English under the document language.', '<p>The chef says: <span lang="fr">Bon appétit !</span></p>', 'The language attribute inherits through nested elements. Place it on the smallest meaningful passage, and avoid wrapping later English text. Proper names, technical terms, indeterminate language, and words that have become part of the surrounding language are exceptions in the criterion. Whether a term qualifies depends on context; do not mark every borrowed word automatically.'),
'3.1.3': ('In a course on security, the word “salt” has a technical meaning distinct from a kitchen ingredient. A link to a general dictionary may lead to the wrong definition. Introduce the precise meaning in the lesson or link directly to a glossary entry.', '<p>A salt is a unique value added before hashing a password. <a href="#glossary-salt">See the glossary entry for salt</a>.</p>', 'An explanation must be discoverable without a pointing device and must reflect the sense used in this passage. Link the term to an actual definition on the same page or a maintained glossary. A definition that only repeats the term does not clarify its meaning. Avoid unexplained jargon in the definition itself.'),
'3.1.4': ('A student sees “DOM” in an introductory lesson for the first time. Using the abbreviation repeatedly without expansion forces them to search elsewhere and choose between different possible meanings. The expansion near the first use makes the lesson self-contained.', '<p>The Document Object Model (DOM) represents the page as a tree of nodes.</p>', 'If the expansion appears in a glossary instead, make the glossary available using an accessible link. An abbreviation that is part of the language may fall under the criterion’s exception. An abbr title alone can be difficult to discover with touch or keyboard, so visible expansion can be more useful even where other techniques are supported.'),
'3.1.5': ('A benefits application explains an appeal using several long sentences and unfamiliar legal expressions. A plain-language version can explain the deadline and next step, while retaining the original details. Compare both versions so the shorter version does not accidentally omit the right to appeal.', '<h2>Plain-language summary</h2>\n<p>If you disagree, send an appeal by the date on your notice.</p>', 'The criterion applies where text requires reading ability more advanced than lower secondary education after proper names and titles are removed. Supplemental content or a version below that threshold is required in the applicable case. A readability score may guide editing but cannot reliably establish whether a person understands the task; test comprehension with readers.'),
'3.1.6': ('An instructional sentence contains a word whose spelling permits two pronunciations with different meanings. If context does not resolve the ambiguity, readers need a way to determine the intended pronunciation. A short textual pronunciation guide adjacent to that occurrence can clarify the intended sense.', '<p>Please record (ri-KORD) the result in your notebook.</p>', 'A guide should be accurate for the intended language and dialect and understandable to its audience. Where phonetic notation is used, explain the notation or provide another accessible form. The criterion is not a requirement to annotate every word; it targets words whose meaning is ambiguous without pronunciation.'),
'3.2.1': ('A menu item triggers location.assign when it receives focus. A keyboard user presses Tab to find the next control, but the browser immediately navigates away. Replace the focus handler with an ordinary link so focus and activation remain separate.', '<a href="/courses">Courses</a>', 'A native link is activated intentionally; reaching it with Tab should not navigate. Check both keyboard and script-driven focus. Showing a focus ring is expected and helpful, while a substantial context change such as navigating to another page on focus is the issue. An example alone cannot establish whether the surrounding page conforms.'),
'3.2.2': ('A course filter redirects on every select change. Arrow-key users may trigger navigation while moving through options. An explicit submit action lets them inspect and revise their choice before the application changes context.', '<form action="/courses">\n  <label for="level">Level</label>\n  <select id="level" name="level"><option>Beginner</option><option>Advanced</option></select>\n  <button type="submit">Apply filter</button>\n</form>', 'If a change of setting will cause a change of context, an alternative is to inform users before the control is used. Keep the notice near the control and available programmatically. Updating results in place does not necessarily change context, but unexpected focus moves, navigation, or submission need careful evaluation.'),
'3.2.3': ('The course site repeats Home, Courses, and Help in its header. On one page the order is Home, Help, Courses. A learner relying on a familiar sequence now has to search again. Restore the relative order of the repeated links across pages.', '<nav aria-label="Main"><a href="/">Home</a> <a href="/courses">Courses</a> <a href="/help">Help</a></nav>', 'Relative order does not prohibit adding page-specific links or changing the menu when the user requests it. Compare the set of pages where the navigation recurs. A menu collapsed at a narrow viewport should still provide an understandable and consistent sequence when opened.'),
'3.2.4': ('The search function appears on two pages. One control has visible text “Search” and the other is a magnifier announced as “Submit”; both perform the same search. Align their visible and accessible names so the function remains recognizable.', '<button type="submit">Search</button>', 'The criterion addresses components with the same functionality within a set of pages. Context can affect what a control does, so compare actual behavior as well as the icon. If two controls have different functions, making their names artificially identical may create a new problem.'),
'3.2.5': ('An online tutorial automatically opens the next page after a timer. The learner may still be reading or may use a different reading pace. Replace the automatic transition with a Next button, or offer a mechanism to turn the automatic change off.', '<button type="button" id="next-lesson">Next lesson</button>', 'A change of context is not the same as every update to a page. Assess whether the change substantially alters the user’s experience, such as a new page or a disruptive focus move. The AAA criterion applies to context changes generally, beyond the specific focus and input rules. Test automatic transitions after a page has been left open.'),
'3.2.6': ('A course site includes the same Help link in the header on several pages. Moving it between the header and footer makes it harder for a learner to find when stuck. Give the repeated help link a consistent relative position.', '<header><nav aria-label="Main"><a href="/courses">Courses</a> <a href="/help">Help</a></nav></header>', 'The rule applies to repeated help mechanisms of the specified types, such as contact details or self-help. It does not require an organization to add a help mechanism to every page. A user may initiate a change in relative order; document such customizations separately from the default layout.'),
'3.3.1': ('A registration form detects a missing email and shows only a red border. Someone who cannot perceive the color receives no explanation. Add text that identifies the affected input and describes the problem.', '<label for="email">Email address</label>\n<input id="email" name="email" aria-invalid="true" aria-describedby="email-error">\n<p id="email-error">Enter your email address.</p>', 'Set the invalid state after a validation failure rather than labeling an untouched valid field as invalid. Make the error discoverable when it appears and preserve the user’s other entries. A field-specific message tells the user more than a generic alert; test the message association with the browser accessibility tree.'),
'3.3.2': ('A date field displays only “MM/DD/YYYY” as a placeholder. Once the user types, that text disappears, and they can no longer see whether the field asks for a birthday or an appointment date. A persistent label and visible instruction solve different parts of the problem.', '<label for="start">Course start date</label>\n<p id="start-help">Use MM/DD/YYYY.</p>\n<input id="start" name="start" aria-describedby="start-help">', 'A label names the field; instructions describe additional expectations such as the format. Provide both when necessary. An accessible name that exists only in hidden text may help a screen-reader user but leave a sighted user without a visible instruction. Validate with real users and keyboard input.'),
'3.3.3': ('A user enters a date in the wrong format and sees only “Invalid”. The system knows which format it accepts, so it can give a useful, safe suggestion. Place that guidance with the identified field and retain the entered value for correction.', '<p id="date-error">Enter the date as MM/DD/YYYY, for example 03/15/2026.</p>', 'Do not provide a correction if doing so compromises security or the content’s purpose. For example, a sign-in failure should not reveal confidential account information. Suggestions complement error identification: the user still needs to know which input is affected and be able to correct it.'),
'3.3.4': ('A learner pays a course fee and accidentally chooses the wrong recipient. A review step can present the recipient and amount and allow correction before committing the payment. The user should be able to go back without losing the entire form.', '<h2>Review payment</h2>\n<p>Recipient: Course office</p>\n<p>Amount: 500 pesos</p>\n<a href="/payment/edit">Edit payment</a>\n<button>Confirm payment</button>', 'The criterion permits a covered submission to be reversible, checked for errors with a chance to correct, or reviewed, confirmed, and corrected before final submission. A vague “Are you sure?” dialog is weak if it gives no way to inspect or correct the details. Check the full criterion for covered legal commitments, financial transactions, user-controlled data, and test responses.'),
'3.3.5': ('A learner filling a username field does not know which characters are accepted. Context-sensitive help placed beside the field can answer that question before submission and reduce trial and error.', '<label for="username">Username</label>\n<p id="username-help">Use 3–20 letters or numbers.</p>\n<input id="username" aria-describedby="username-help">', 'The example is an instructional pattern; actual restrictions must match server validation. A more complex explanation may use a help link or dialog if it remains keyboard accessible and does not discard the form. Context-sensitive help differs from a broad support page because it addresses the user’s immediate input or task.'),
'3.3.6': ('A learner changes a public profile description and submits the wrong text. An Undo action that restores the previous description can protect the submission. A review-and-correct step or relevant input checks with correction are other approaches.', '<p>Profile saved. <button type="button">Undo change</button></p>', 'The button is only an illustration: application code must actually restore the previous value, communicate whether the undo succeeded, and make the action available long enough to use. The enhanced criterion extends the safeguards to submissions of information by the user more generally; a decorative confirmation button alone is not a safeguard.'),
'3.3.7': ('A checkout asks for a shipping address on the first step and the same address again on the payment step. Offer the previous address as a selectable billing address, while still allowing a different one.', '<label><input type="checkbox" name="same-address"> Use my shipping address for billing</label>', 'The application must retain and apply the earlier information when the user selects it; the checkbox by itself does not perform that work. Exceptions cover cases where re-entry is essential, necessary for security, or the earlier information is no longer valid. Check that the selection remains editable and that stored personal information is handled appropriately.'),
'3.3.8': ('A password field blocks paste and password-manager filling. This forces a person to remember and manually transcribe a secret. Allowing paste and compatible autofill can provide assistance with that cognitive task.', '<label for="password">Password</label>\n<input id="password" type="password" name="password" autocomplete="current-password">', 'Avoid scripts that intercept and cancel paste. Test the actual sign-in flow, including any second-factor challenge and recovery. The minimum criterion provides exceptions for object recognition and identification of personal content; an alternative or an assisting mechanism may also address the requirement. A single HTML attribute does not by itself prove the complete process is accessible.'),
'3.3.9': ('A sign-in asks a user to choose their own photograph as an authentication challenge. That can qualify for an exception at the minimum level, but the enhanced criterion does not retain the exception. Provide an accessible alternative or assistance with the cognitive function test.', '<button type="button">Sign in with a passkey</button>', 'This is an interface illustration rather than a complete passkey implementation. Test whether the chosen method and its enrollment, second-factor, and account-recovery steps are accessible to the intended user. The enhanced criterion removes the object-recognition and personal-content exceptions but retains the possibility of an alternative or assisting mechanism.')
}

EDGE_CASES = {
'3.1.1': ('Checking a multilingual page', 'A language tag should describe the language of the document, including templates generated after a visitor changes the interface language. Check both initial server output and the final DOM after a client-side language switch. The title, navigation, form messages and main text may not all be translated at once. If one translation is incomplete, decide which language predominates and mark applicable passages in another language separately.', 'A valid tag such as en, fil or fr conveys language, while a regional subtag can add detail when useful. Inventing a tag or using a country flag as the only indicator does not supply equivalent machine-readable information. Testing should include a browser inspector and, when available, a screen reader configured to change voices by language. Voice availability varies, so inspect the markup as well as listening.'),
'3.1.2': ('Language changes within components', 'A language switch can occur inside a button name, a heading, or a quotation. Place the language attribute on the element containing the translated passage, and verify the attribute remains present after the framework renders or updates the page. Nested attributes can switch back to the surrounding language if a passage contains another embedded language.', 'A product name in a different language is not automatically a failure: proper names and technical terms are among the stated exceptions. Consider a name that is also an ordinary foreign-language sentence separately rather than applying a blanket rule. Inspect the accessibility tree and listen to a representative passage; pronunciation depends on available speech voices and language-switching settings.'),
'3.1.3': ('Choosing an explanation', 'A security lesson might use “salt” both as a general word and as a technical term. Define the technical sense where that meaning first matters; use an anchor that points to a real glossary entry when the explanation is longer. An in-page definition saves navigation, while a glossary can consolidate longer definitions shared across lessons. Both need clear, accessible links and accurate content.', 'Review expressions whose meaning cannot be inferred from ordinary usage, including idioms used metaphorically. An explanation must clarify the intended sense in that passage, not simply repeat the expression. Ask a learner to describe the term in their own words and trace the glossary link with keyboard and screen reader. This is a content review as well as a link test.'),
'3.1.4': ('Repeated abbreviations and navigation', 'A long course may introduce an abbreviation on one page and use it again on another. Readers can enter on the second page from a search result, so a page-level expansion or glossary link can be more useful than relying on an explanation in an earlier lesson. If the same letters have different meanings in different fields, provide the expansion that matches the current usage.', 'Acronyms can be understandable to experienced developers while confusing new students. Expand them without making the sentence unnecessarily difficult: write the full phrase first, then the abbreviation in parentheses. Check touch and keyboard access if a tooltip supplements that explanation. The requirement allows specified exceptions, so assess the actual abbreviation rather than assuming every shortened form needs identical treatment.'),
'3.1.5': ('Evaluating a simpler version', 'Reading difficulty is not a measure of intelligence or a reason to remove important details. Break a complex requirement into steps, define essential vocabulary, and retain conditions and deadlines. A visual explanation can help some readers, but it needs a text alternative that conveys its information. If a simplified version is provided, keep it current whenever the authoritative original changes.', 'Ask a reader to perform a real task with the explanation, such as identifying what document to submit and when. Note hesitations and incorrect assumptions, then revise. Readability formulas can suggest passages to inspect, but a numerical score alone is not a reliable accessibility verdict. The criterion uses lower secondary education as the threshold after removing proper names and titles.'),
'3.1.6': ('Clarifying meaning without relying on sound', 'An audio recording can demonstrate pronunciation, but it is not sufficient help for someone who cannot hear it. A readable pronunciation guide can accompany audio. Different dialects may pronounce the same word differently, so state the intended meaning and use a notation familiar to the audience; ask a language specialist to check difficult examples.', 'Do not assume that a speech synthesizer will infer the intended pronunciation correctly from surrounding words. Test the specific occurrence and verify that the learner can locate its guide. The criterion concerns words whose meaning is ambiguous without knowing their pronunciation, not every uncommon spelling. A definition and a pronunciation guide solve related but distinct problems.'),
'3.2.1': ('Focus, activation and state updates', 'Focus may arrive through Tab, a screen reader command, or a script that returns the user to a validation error. A redirect attached to the focus event can therefore interrupt navigation in several ways. Remove the redirect and trigger the consequential action from an explicit link or button instead. Retaining visible focus helps users understand where they are before deciding to activate anything.', 'A tooltip or focus styling is not automatically a change of context. Evaluate the actual result: did the page navigate, open a new window, move focus elsewhere, or otherwise substantially change the user’s interaction? Test both forward and backward keyboard navigation, and verify the browser location and active element before and after focus arrives.'),
'3.2.2': ('Handling selectors and automatic updates', 'A selector may change a preview in the current page without moving focus; a selector that submits an entire form or changes location creates a different experience. Record the effect rather than assuming every input event is a context change. An explicit Apply button is often easier to understand, particularly when a user wants to compare several options before committing.', 'If the design intentionally changes context as soon as a setting changes, inform the user before they interact with that control. A warning shown only after selection comes too late. Test using keyboard arrows and screen reader interaction as well as pointer input. Check that a user can change their selection without accidentally losing other form entries.'),
'3.2.3': ('Order across pages and layouts', 'Suppose Courses appears between Home and Help on desktop, but a redesigned lesson template moves Help before Courses. Both pages contain all three links, yet their relative order differs. A consistent sequence helps users who navigate by position or by repeated keystrokes. A page-specific link can be added without changing the sequence of links that recur.', 'Responsive layouts may rearrange visual elements, collapse navigation, or expose a different source order. Test the repeated navigation in both its open mobile state and desktop presentation. A user may initiate a change in order, such as choosing a personalized menu; document the chosen state separately from unexpected template changes.'),
'3.2.4': ('Names, icons and actual function', 'An icon and its accessible name may disagree. A magnifier announced as “Go” on one page and “Search” on another can make a repeated search feature harder to recognize. Inspect both the visible label and the computed accessible name. If an icon is accompanied by text, avoid introducing a conflicting aria-label that overrides that text.', 'A site can have more than one kind of search, such as searching lessons and searching support articles. Decide whether the controls truly have the same function before forcing identical labels. The criterion concerns consistency of identification across the relevant set of pages; matching colors or positioning alone do not establish it.'),
'3.2.5': ('Automatic transitions and user choice', 'A timed tutorial might open the next lesson automatically after a video. A learner who needs extra time may lose the current position. Give them control before the transition, for example by disabling automatic progression or choosing a Next action. If there is an on/off setting, make its current state and effect clear and allow it to be operated from the keyboard.', 'Check transitions caused by timers, focus, input, and background events. This criterion is broader than focus-only and input-only requirements, so a page can pass one of those and still need review here. Distinguish replacing a small piece of content from a change that alters the page, focus or other context in a substantial way.'),
'3.2.6': ('Help across a set of pages', 'A learner may first find the support link while browsing a course and later need it when a form fails. Reusing the same position in the page structure helps them find it again. Record the help link relative to surrounding navigation, not merely whether a help icon exists somewhere on each page.', 'The criterion covers specified repeated help mechanisms, including human contact details or methods, self-help, and fully automated contact mechanisms. It does not demand the creation of a particular help service. A user-initiated change in order is allowed. Test repeated mechanisms across pages in the same set and inspect both mobile and desktop layouts.'),
'3.3.1': ('Communicating a failed submission', 'A form can show a summary near the top and a field-specific message near each invalid control. A summary helps users see the scope of the problem, while the local message helps them correct it. Link the summary to the relevant fields and make the association with each error available programmatically. Preserve entered values so correction does not become a new task.', 'Test missing, malformed, and server-rejected inputs. An error must identify the item and describe the problem in text; color or an unexplained icon alone is insufficient. Check how a dynamically inserted message is announced, where focus goes after submission, and whether the same message remains discoverable when the learner returns to the field.'),
'3.3.2': ('Labels, instructions and grouping', 'A label answers “What is this input?” Instructions answer “What details do I need to provide?” For a telephone field, a visible label can identify the field and nearby text can explain whether a country code is required. Instructions should match the actual accepted formats and remain available after typing begins.', 'For a set of related options, use a group label as well as individual option labels. Native fieldset and legend are useful for related radio buttons and checkboxes. Test the complete accessible name and associated description; a placeholder, color-coded asterisk, or icon alone may not explain requirements to every learner.'),
'3.3.3': ('Actionable and safe correction', 'A suggestion should tell the user what to do next, not merely restate that the value is wrong. For a date with a known expected format, offer the format and a realistic example. For a value outside an accepted range, provide the range when it is safe to do so. Keep the original value available so the user can edit it.', 'Security and purpose matter. A sign-in message that distinguishes an unknown account from a wrong password may reveal information an attacker can use; a general credential message may be appropriate. This criterion applies when a suggestion is known, unless disclosure would jeopardize security or the purpose of the content. Pair it with clear error identification.'),
'3.3.4': ('Selecting and testing a safeguard', 'A reversible transaction requires a practical way to reverse the result, not just a promise that support might help. An input-checking approach must identify detected errors and let the user correct them. A review approach must show meaningful data before final submission, allow corrections, and clearly distinguish the final confirmation action from editing.', 'Walk through a test payment with a deliberately incorrect amount. Verify the learner can notice and correct it before commitment or use the chosen safeguard afterward. The criterion covers specified legal, financial, user-controlled data and test-response situations; verify the full scope and any exceptions rather than assuming it applies identically to all forms.'),
'3.3.5': ('Making help available at the point of need', 'Help can be directly visible, linked from the control, or provided through another accessible mechanism. Inline help reduces navigation, but a long explanation may work better in a linked section or dialog. In either case, describe the specific information needed for the current field and provide an example consistent with validation rules.', 'Test that opening help does not clear the form. If a dialog opens, focus should enter it, the help should be readable, and closing it should return the user to a sensible location. Do not rely on a mouse-only hover effect. Validate the text after requirements change so it does not instruct users to enter a value the application rejects.'),
'3.3.6': ('Safeguards for ordinary submissions', 'Consider a learner updating a profile. Undo is convenient when it is reliable and discoverable; review can be preferable where changes have visible consequences; input checking is useful when the system can identify errors. Each approach has different implementation and testing costs. Select one of the specified safeguards and verify it works for the submission.', 'If an Undo control appears, test restoring the earlier value and communicating success or failure. If validation is the safeguard, submit a detectable error and verify a correction opportunity. If review is used, change a value at review and ensure the final submission includes the corrected data. The enhanced criterion covers user submissions more broadly than the AA criterion.'),
'3.3.7': ('Same-process reuse and exceptions', 'In a checkout, a customer may need a billing address that differs from shipping. Reuse should therefore be an offered choice or editable prefilled value, not a forced assumption that both addresses are identical. Make it clear what information was carried forward and provide an easy way to correct it.', 'The rule concerns previously entered or supplied information needed again in the same process. Re-entry can still be necessary when it is essential, required for security, or the previous information is no longer valid. Evaluate the reason rather than treating every repeat field as automatically forbidden. Verify the selected value reaches the final submission correctly.'),
'3.3.8': ('Evaluate every authentication step', 'A sign-in can appear accessible while account recovery or a second factor blocks paste or demands memorizing a code. Trace the complete path a learner must take, including failed sign-in, recovery and any required second factor. Identify the cognitive task at each step, then check for an alternative or an assisting mechanism that the learner can actually use.', 'Password-manager support, paste, and device mechanisms are potential assistance, but their effectiveness depends on implementation and user access. The minimum criterion includes specified exceptions for recognizing objects and identifying personal content. It does not follow that every CAPTCHA or photograph challenge is accessible for everyone; test the actual path with intended users.'),
'3.3.9': ('Enhanced authentication and recovery', 'The enhanced criterion removes the object-recognition and personal-content exceptions that appear at the minimum level. A photograph-selection challenge cannot rely on those exceptions to meet the enhanced requirement. If it uses a cognitive function test, provide an alternative that avoids the test or a mechanism that assists with completing it.', 'A passkey button is not enough to assess the whole service. Can the learner enroll, use an available device, complete any second factor, and recover an account without an inaccessible cognitive test? Check alternative paths where devices are unavailable and verify that help and instructions are usable. Security mechanisms must actually work; a label describing an option is only the beginning of implementation.')
}

def paragraph(text):
    return {'type': 'paragraph', 'content': [{'type': 'text', 'text': text}]}

def heading(text):
    return {'type': 'heading', 'attrs': {'level': 2}, 'content': [{'type': 'text', 'text': text}]}

def assessment(title, rows, offset=0):
    elements, key, explanation = [], {}, {}
    for n, (question, right, wrong, why) in enumerate(rows, 1):
        name = f'q{n}'
        choices = [right, wrong] if (n + offset) % 2 else [wrong, right]
        elements.append({'type': 'radiogroup', 'name': name, 'title': question, 'choices': choices, 'isRequired': True})
        key[name], explanation[name] = right, why
    return {'questions': {'title': title, 'pages': [{'name': 'page1', 'title': 'Knowledge check', 'elements': elements}]}, 'answer_key': key, 'explanations': explanation, 'passing_percent': 70, 'max_attempts': 3}

def main():
    reference = json.loads(REFERENCE.read_text(encoding='utf-8-sig'))
    principle = next(x for x in reference if x['principle'] == 'Understandable')
    criteria = {s['title'].split()[0]: s for g in principle['lessons'] for s in g['sublessons']}
    if set(EXTENSION) != set(criteria):
        raise ValueError('Additional teaching coverage mismatch')
    if set(WALKTHROUGHS) != set(criteria):
        raise ValueError('Walkthrough coverage mismatch')
    if set(DECISIONS) != set(criteria):
        raise ValueError('Scenario analysis coverage mismatch')
    if set(REVIEW) != set(criteria):
        raise ValueError('Review case coverage mismatch')
    if set(CASES) != set(criteria):
        raise ValueError('Assessment scenario coverage mismatch')
    lessons = []
    for code, objective, intro, instruction, testing, activity, question, right, wrong, explanation in DATA:
        criterion = criteria[code]
        title, level = criterion['title'], criterion['level']
        edge_title, edge_context, edge_test = EDGE_CASES[code]
        example, code_example, rationale = DETAILS[code]
        extension_title, extension_context, extension_test = EXTENSION[code]
        walkthrough_title, *walkthrough_paragraphs = WALKTHROUGHS[code]
        content = {'type': 'doc', 'content': [heading('Learning objectives'), paragraph(objective + f'. This lesson addresses WCAG 2.2 {title} (Level {level}).'), heading('Why this matters'), paragraph(intro), heading('How to apply the criterion'), paragraph(instruction), heading('Real-world example'), paragraph(example), {'type': 'codeBlock', 'content': [{'type': 'text', 'text': code_example}]}, paragraph(rationale), heading('Review and testing'), paragraph(testing), heading(edge_title), paragraph(edge_context), paragraph(edge_test), heading('Knowledge check'), paragraph(question + ' Consider the consequences of each approach before continuing.'), heading('Required practical activity'), paragraph(activity + ' Record the barrier, the change you made, and the evidence from your test.'), heading('Key takeaway'), paragraph(explanation + ' Consult the complete WCAG 2.2 criterion for its scope and exceptions.'), paragraph('Reference: https://www.w3.org/TR/WCAG22/')]}
        # Put the added explanation before the check and required activity.
        check_index = next(i for i, node in enumerate(content['content']) if node.get('type') == 'heading' and node['content'][0]['text'] == 'Knowledge check')
        content['content'][check_index:check_index] = [heading(extension_title), paragraph(extension_context), paragraph(extension_test), heading(walkthrough_title), *[paragraph(item) for item in walkthrough_paragraphs], heading('Apply the distinction'), paragraph(DECISIONS[code]), heading('Review a second case'), paragraph(REVIEW[code]), heading('Implementation and verification'), paragraph(PRACTICE[code]), paragraph(GROUP_GUIDANCE[code[:3]])]
        case_question, case_right, case_wrong, review_wrong, *_ = CASES[code]
        mini = [(question, right, wrong, explanation), (case_question, case_right, case_wrong, case_right), (f'Which review approach checks {title}?', activity, review_wrong, activity)]
        lessons.append({'title': title, 'objective': objective, 'content': content, 'assessment': assessment(title + ' mini-assessment', mini, len(lessons))})
    if {r[0] for r in DATA} != set(criteria):
        raise ValueError('Reference coverage mismatch')
    if set(PRE_CASES) != {r[0] for r in DATA[::2]}:
        raise ValueError('Pre-assessment scenario coverage mismatch')
    pre_rows = [PRE_CASES[r[0]] for r in DATA[::2]]
    post_rows = [(CASES[r[0]][4], CASES[r[0]][5], CASES[r[0]][6], CASES[r[0]][5]) for r in DATA]
    output = {'principle': 'Understandable', 'lessons': lessons, 'pre': assessment('Understandable pre-assessment', pre_rows), 'post': assessment('Understandable post-assessment', post_rows)}
    Path(__file__).with_name('understandable.json').write_text(json.dumps(output, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

if __name__ == '__main__':
    main()
